<template><main class="max-w-6xl mx-auto p-4 sm:p-6"><div class="mb-6"><h1 class="text-2xl font-bold">กำหนดประเภทบุคลากร</h1><p class="text-sm text-gray-500">ประเภทบุคลากรเป็นตัวกำหนดสิทธิ์และหลักเกณฑ์วันลา</p></div><div class="bg-white border rounded-2xl overflow-hidden"><div class="p-4 border-b"><input v-model="search" placeholder="ค้นหาชื่อหรือหน่วยงาน" class="w-full max-w-md border rounded-xl px-4 py-2"></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-50"><tr><th class="p-3 text-left">บุคลากร</th><th class="p-3 text-left">หน่วยงาน</th><th class="p-3 text-left">ประเภทบุคลากร</th><th class="p-3">สถานะ</th></tr></thead><tbody><tr v-for="u in filtered" :key="u.id" class="border-t"><td class="p-3 font-medium">{{u.name}}</td><td class="p-3">{{u.department?.name||'-'}}</td><td class="p-3"><select :value="u.personnel_type_id" @change="assign(u,$event.target.value)" class="border rounded-lg px-3 py-2 min-w-48"><option value="" disabled>กรุณากำหนด</option><option v-for="p in types" :key="p.id" :value="p.id">{{p.name}}</option></select></td><td class="p-3 text-center"><span :class="u.personnel_type_id?'text-green-700 bg-green-50':'text-red-700 bg-red-50'" class="rounded-full px-2 py-1 text-xs">{{u.personnel_type_id?'พร้อมใช้งาน':'ยังไม่กำหนด'}}</span></td></tr></tbody></table></div></div></main></template>
<script setup>import{ref,computed,onMounted}from'vue';import api from '../../axios';import{useAlertStore}from'../../stores/alert';const users=ref([]),types=ref([]),search=ref(''),alerts=useAlertStore();const load=async()=>{const[a,b]=await Promise.all([api.get('/admin/users'),api.get('/personnel-types')]);users.value=a.data;types.value=b.data};const filtered=computed(()=>{const q=search.value.toLowerCase();return users.value.filter(u=>!q||u.name.toLowerCase().includes(q)||(u.department?.name||'').toLowerCase().includes(q))});const assign=async(u,id)=>{try{await api.put(`/admin/users/${u.id}/personnel-type`,{personnel_type_id:Number(id)});u.personnel_type_id=Number(id);alerts.success('บันทึกประเภทบุคลากรแล้ว')}catch(e){alerts.error(e.response?.data?.message||'บันทึกไม่สำเร็จ');await load()}};onMounted(load);</script>
